// Hidden one-off page (2026-11-09): ONE QHooks Safe transaction that deploys QDrops at a fixed address and funds the
// launch-week drop (Randall approved: 1,000,000 QHOOKS from the marketing tranche). Same flow as /safe-fomo: no Safe
// app, owners approve on chain. Step 1, either owner calls approveHash(hash). Step 2, the other owner calls
// execTransaction with both approved-hash signatures (v=1, r=owner), sorted by owner address.
// The transaction (to, data, delegatecall to MultiSendCallOnly 1.4.1) is fixed in /qx-safe-drops-tx.mjs, generated by
// lead/qdrops/make-safe-tx.mjs and rehearsed on a Robinhood fork (lead/qdrops/safe-rehearsal.mjs). The hash is the
// Safe's own getTransactionHash at its current nonce, so it still works if another Safe transaction lands first.
// Nothing is sent unless an eth_call of the exact transaction succeeds from the connected owner.
import {getWalletHub} from "/wallet-hub-fresh.mjs";
import {chainById} from "/chains.mjs";
import {TX} from "/qx-safe-drops-tx.mjs";
import {safeHashCall,safeExecData} from "/qdrops-core.mjs";
const hub=getWalletHub(window),root=document.getElementById("qsd-root");
const OWNERS=[{a:"0x88db60586866294409e47bbbb0b436104f09c1b5",name:"Qhooks 1",full:"0x88Db60586866294409E47BbBb0b436104F09c1B5"},
 {a:"0x9b13398df547c18e68d1cfe086ff1cb5f1a84127",name:"Qhooks2",full:"0x9B13398dF547C18e68d1cFE086Ff1cb5F1a84127"}];
const AMOUNT=BigInt(TX.amount);
const el=(tag,attrs={},...kids)=>{const n=document.createElement(tag);for(const[k,v]of Object.entries(attrs))if(v!==false&&v!=null)n.setAttribute(k,v===true?"":v);n.append(...kids);return n;};
// Randall's order: /safe-fomo (#2), then /arb2-allow (#3), then this. The hash always follows the Safe's live nonce
// (never a stored one), but signing early would take an earlier page's slot, so wait unless the owner says go.
const AFTER_NONCE=4n;let goAnyway=false;
let busy=false,status={text:"",tone:""};
async function rpc(method,params){
 const r=await fetch(chainById(TX.chain).rpc,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({jsonrpc:"2.0",id:1,method,params})});
 const j=await r.json();if(j.error)throw Error(j.error.message||"Network read failed");return j.result;
}
const call=(to,data,from)=>rpc("eth_call",[{to,data,...(from?{from}:{})},"latest"]);
const pad=a=>a.toLowerCase().slice(2).padStart(64,"0");
const fmt=v=>(v/10n**18n).toLocaleString("en-US");
const getHash=nonce=>safeHashCall(TX,nonce),execData=()=>safeExecData(TX,OWNERS.map(o=>o.a));
async function read(){
 const n=BigInt(await call(TX.safe,"0xaffed0e0")),hash=await call(TX.safe,getHash(n));
 const [a0,a1,sb,code,funded]=await Promise.all([call(TX.safe,"0x7d832974"+pad(OWNERS[0].a)+hash.slice(2)),call(TX.safe,"0x7d832974"+pad(OWNERS[1].a)+hash.slice(2)),
  call(TX.qhooks,"0x70a08231"+pad(TX.safe)),rpc("eth_getCode",[TX.drops,"latest"]),call(TX.qhooks,"0x70a08231"+pad(TX.drops))]);
 return {nonce:n,hash,approved:[BigInt(a0)!==0n,BigInt(a1)!==0n],safeBal:BigInt(sb),deployed:code&&code!=="0x",dropsBal:BigInt(funded)};
}
const say=(text,tone="")=>{status={text,tone};render();};
async function send(kind){
 if(busy)return;let conn=hub.snapshot().current;if(!conn){hub.open();return;}
 busy=true;say("");
 try{
  const s=await read();
  if(s.deployed)throw Error("QDrops is already deployed. Nothing was sent.");
  if(s.nonce<AFTER_NONCE&&!goAnyway)throw Error("Earlier Safe transactions come first. Nothing was sent.");
  if(conn.chainId!==TX.chain){say("Switching your wallet to Robinhood Chain…");conn=await hub.switchChain(TX.chain);if(conn?.chainId!==TX.chain)throw Error("Switch your wallet to Robinhood Chain, then try again.");}
  const from=conn.owner,me=OWNERS.find(o=>o.a===String(from).toLowerCase());
  if(!me)throw Error("This wallet is not an owner of the QHooks Safe. Nothing was sent.");
  const data=kind==="exec"?execData():"0xd4d9bdcd"+s.hash.slice(2),tx={from,to:TX.safe,data,value:"0x0"};
  let sim;try{sim=await call(TX.safe,data,from);}catch(e){throw Error("This would fail right now ("+(e.message||"reverted")+"). Nothing was sent.");}
  if(kind==="exec"&&BigInt(sim||"0x0")!==1n)throw Error("The Safe would not run it right now. Nothing was sent.");
  try{const est=BigInt(await rpc("eth_estimateGas",[{from,to:TX.safe,data,value:"0x0"}]));tx.gas="0x"+(est*13n/10n).toString(16);}
  catch{throw Error("This would fail right now. Nothing was sent.");}
  try{const b=await rpc("eth_getBlockByNumber",["latest",false]),tip=BigInt(await conn.entry.provider.request({method:"eth_maxPriorityFeePerGas"}).catch(()=>"0x0"));
   if(b?.baseFeePerGas){tx.maxPriorityFeePerGas="0x"+tip.toString(16);tx.maxFeePerGas="0x"+(BigInt(b.baseFeePerGas)*2n+tip).toString(16);}}catch{}
  if(hub.snapshot().current?.owner!==from)throw Error("Your wallet changed. Try again.");
  say("Confirm in your wallet…");
  const hash=await conn.entry.provider.request({method:"eth_sendTransaction",params:[tx]});
  say("Sent. Waiting for the network…");
  let r=null;for(let i=0;i<180&&!r;i++){r=await rpc("eth_getTransactionReceipt",[hash]).catch(()=>null);if(!r)await new Promise(res=>setTimeout(res,2000));}
  if(!r)throw Error("Still pending. Check your wallet activity, then reload this page.");
  if(r.status!=="0x1")throw Error("The network refused it. Only gas was spent.");
  const after=await read();
  if(kind==="exec")say(after.deployed&&after.dropsBal===AMOUNT?"Done. QDrops is live at "+TX.drops+" holding 1,000,000 QHOOKS.":"Confirmed. Reload to check the result.",after.deployed?"ok":"");
  else say("Approved.","ok");
 }catch(e){say(/reject|denied|cancel/i.test(e?.message||"")?"Cancelled in your wallet. Nothing was sent.":(e?.message||"That did not go through."),"bad");}
 finally{busy=false;render();}
}
async function render(){
 let s=null;try{s=await read();}catch{}
 const conn=hub.snapshot().current,me=conn&&OWNERS.find(o=>o.a===String(conn.owner).toLowerCase()),other=me&&OWNERS.find(o=>o!==me);
 const facts=el("dl",{},
  el("dt",{},"Deploys"),el("dd",{},"QDrops at "+TX.drops+" on Robinhood Chain"),
  el("dt",{},"Owner"),el("dd",{},"QHooks Safe "+TX.safe+" (only it can change settings, with 7 days' public notice, or sweep funds no list covers, with 30 days' notice)"),
  el("dt",{},"Posts the lists"),el("dd",{},TX.rooter+" (the QHooks keeper; can only propose lists inside the budget)"),
  el("dt",{},"Can stop a list"),el("dd",{},"Qhooks 1 "+OWNERS[0].full+" alone, or the Safe, during each list's 24-hour hold"),
  el("dt",{},"Funds"),el("dd",{},"1,000,000 QHOOKS from the Safe for the launch-week drop. WETH is listed for callout rewards, with no deposit yet."),
  el("dt",{},"Safe holds"),el("dd",{},s?fmt(s.safeBal)+" QHOOKS":"Refreshing…"),
  el("dt",{},"Safe transaction"),el("dd",{},s?"#"+s.nonce+" · "+s.hash:"Refreshing…"),
  ...OWNERS.flatMap(o=>[el("dt",{},o.name),el("dd",{},o.full+" · "+(!s?"Refreshing…":s.approved[OWNERS.indexOf(o)]?"approved":"not yet"))]));
 let label="Connect an owner wallet",action=()=>hub.open(),disabled=busy,note="";
 if(!s){disabled=true;label="Refreshing…";}
 else if(s.deployed){disabled=true;label="Already done";note="QDrops is live at "+TX.drops+" and holds "+fmt(s.dropsBal)+" QHOOKS.";}
 else if(s.nonce<AFTER_NONCE&&!goAnyway){disabled=true;label="Waiting for earlier Safe transactions";
  note="The Safe is at transaction #"+s.nonce+". Sign /safe-fomo (#2) and /arb2-allow (#3) first; this page then signs #4. Skipping them? Use the button below.";}
 else if(s.safeBal<AMOUNT){disabled=true;label="Not available";note="The Safe holds less than 1,000,000 QHOOKS.";}
 else if(conn&&!me){label="Switch to an owner wallet";note="This wallet is not an owner. Connect Qhooks 1 or Qhooks2.";}
 else if(me){const i=OWNERS.indexOf(me),j=1-i;
  if(s.approved[j]){label="Step 2: Deploy and fund";action=()=>send("exec");note=OWNERS[j].name+" has approved. Sending from "+me.name+" completes it.";}
  else if(s.approved[i]){disabled=true;label="Waiting for "+other.name;note="Approved by "+me.name+". Open this page with "+other.name+" ("+other.full+") to send.";}
  else{label="Step 1: Approve as "+me.name;action=()=>send("approve");note="Then open this page with "+other.name+" to send.";}}
 const btn=el("button",{type:"button",class:"qtx-mini qas-go",disabled},label);btn.addEventListener("click",action);
 const extra=[];
 if(s&&!s.deployed&&s.nonce<AFTER_NONCE&&!goAnyway){const skip=el("button",{type:"button",class:"qtx-mini"},"Skip them and use #"+s.nonce+" now");skip.addEventListener("click",()=>{goAnyway=true;render();});extra.push(skip);}
 root.replaceChildren(facts,el("p",{},note),btn,...extra,el("p",{class:"qas-status",role:"status","aria-live":"polite","data-tone":status.tone||false},status.text));
}
render().catch(e=>{root.textContent=e.message;});
hub.subscribe(()=>render());
